  function goodbye(){const v=vals('goodbye',{enabled:false,channel:'general',message:tr('Sampai jumpa, {username}!','Goodbye, {username}!'),ping:false});return `<div class="f-layout"><div>${card(tr('Pesan goodbye','Goodbye message'),tr('Contoh tampilan. Tidak tersimpan dan tidak mengirim pesan.','Sample appearance. Not saved and does not send a message.'),form('goodbye',check('enabled',tr('Aktifkan goodbye','Enable goodbye'),tr('Pesan saat anggota keluar.','Message when a member leaves.'),v.enabled)+select('channel',tr('Channel goodbye','Goodbye channel'),tr('Channel teks.','Text channel.'),v.channel,chans)+textarea('message',tr('Pesan','Message'),tr('Variabel: {user}, {username}, {server}, {memberCount}.','Variables: {user}, {username}, {server}, {memberCount}.'),v.message)+check('ping',tr('Ping anggota','Ping member'),tr('Mention anggota pada pesan.','Mention the member in the message.'),v.ping)))}</div><aside>${card(tr('Pratinjau','Preview'),tr('Hanya contoh statis.','Static example only.'),tr('<p class="f-muted">Buka dashboard bot yang terautentikasi untuk mengelola pengaturan.</p>','<p class="f-muted">Open the authenticated bot dashboard to manage settings.</p>'))}</aside></div>`;}
