   const v=vals('ticket',{channel:'ticket',staff:'staff',open:'open',closed:'closed',message:tr('Butuh bantuan? Buat tiket di sini.','Need help? Create a ticket here.'),max:'2',dm:true,logs:'logs'});return `<div class="f-layout"><div>${card(tr('Panel ticket','Ticket panel'),tr('Atur tempat dan alur bantuan untuk anggota.','Configure the location and support flow for members.'),form('ticket',select('channel',tr('Channel panel','Panel channel'),tr('Tempat tombol membuat tiket.','Where the ticket creation button appears.'),v.channel,chans)+select('staff',tr('Role staf','Staff role'),tr('Role yang menangani tiket.','Role that handles tickets.'),v.staff,roles)+select('open',tr('Kategori tiket terbuka','Open ticket category'),tr('Kategori untuk tiket aktif.','Category for active tickets.'),v.open,[['open',tr('Tiket Terbuka','Open Tickets')],['support','Support']])+select('closed',tr('Kategori tiket tertutup','Closed ticket category'),tr('Kategori untuk tiket yang selesai.','Category for completed tickets.'),v.closed,[['closed',tr('Tiket Tertutup','Closed Tickets')],['archive',tr('Arsip','Archive')]])+textarea('message',tr('Pesan panel','Panel message'),tr('Pesan yang muncul pada panel.','Message displayed on the panel.'),v.message)+text('max',tr('Maksimum tiket per anggota','Maximum tickets per member'),tr('Jumlah tiket aktif per anggota.','Number of active tickets per member.'),v.max,'number')+check('dm',tr('DM saat ditutup','DM when closed'),tr('Kirim pemberitahuan ketika tiket ditutup.','Send a notification when a ticket is closed.'),v.dm)+select('logs',tr('Channel log ticket','Ticket log channel'),tr('Catatan aktivitas tiket.','Ticket activity records.'),v.logs,chans)))}</div><aside>${card(tr('Preview panel','Panel preview'),tr('Tampilan contoh panel Discord.','Sample Discord panel appearance.'),`<div class="discord-demo"><div class="discord-avatar">Z</div><div class="discord-copy"><div><strong>ZentixBot</strong> <span class="discord-bot">BOT</span></div><div class="discord-embed"><b>🎫 Ticket support</b><p>${escapeHTML(v.message)}</p></div><button type="button" class="discord-button" data-sim-action="${tr('Buat tiket','Create ticket')}">${tr('Buat Ticket','Create Ticket')}</button></div></div><div class="f-preview-action">${action(tr('Perbarui panel','Update panel'))}</div>`)}<p class="f-aside-note">${tr('PANEL CONTOH','SAMPLE PANEL')}<br>${tr('Tidak akan dikirim ke Discord.','Will not be sent to Discord.')}</p></aside></div>`;
